        internal static void Need(bool ok, string text) { if (!ok) throw new Exception(text); }
        internal static string Hash(byte[] bytes)
        { using (var h = SHA256.Create()) return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-", ""); }
        internal static bool Reject(Action action)
        { try { action(); return false; } catch (ArgumentException) { return true; } catch (InvalidDataException) { return true; } catch (NotSupportedException) { return true; } }
        internal static void Integer(byte[] b, int at, int value) { BitConverter.GetBytes(value).CopyTo(b, at); }
        internal static void Word(byte[] b, int at, int value) { BitConverter.GetBytes(unchecked((short)value)).CopyTo(b, at); }
        internal static byte[] Read(BinaryReader r, int size)
        { var b = r.ReadBytes(size); Need(b.Length == size, "Truncated idle capture"); return b; }
        internal static byte[] Patch(BinaryReader r, byte[] basis)
        {
            var b = (byte[])basis.Clone(); int count = r.ReadInt32(), last = -1;
            Need(count >= 0 && count <= b.Length, "Idle delta count");
            for (int n = 0; n < count; n++)
            { int at = r.ReadInt32(); Need(at > last && at < b.Length, "Idle delta order/bounds"); last = at; b[at] = r.ReadByte(); }
            return b;
        }
        internal static byte[][] Bases(string assets)
        { return new[] { PracticeProducedMissChecks.Boundary(assets, 0).CopyFleetPool(), PracticeProducedMissChecks.Boundary(assets, 1).CopyFleetPool() }; }

        internal static void Fixture(byte[] basis, int id, int actor, int slot, int state, int profile,
                                     bool whole, out byte[] fleets, out PracticeAiSharedBacking backing)
        {
            var f = (byte[])basis.Clone(); var r = new byte[78560];
            if (whole) for (int g = 0; g < 250; g++) PracticeFleetServiceContext.CreateDiagnostic(g).CopyTo(r, g * 312);
            else for (int n = 0; n < r.Length; n++) r[n] = (byte)(n * 29 + 17);
            int at = actor * 492, ta = slot * 312, home = profile == 0 ? 0 : profile == 1 ? 249 : 16;
            Integer(f, at + 472, state); Word(f, at + 488, home);
            for (int n = 0; n < 5; n++) { Word(f, at + 40 + n * 2, 100 + n * 10); Word(f, at + 50 + n * 2, 200 + n * 10); }
            if (profile == 1) { Word(f, at + 12, -10); Word(f, at + 14, -20); Word(f, home * 492 + 12, -32768); Word(f, home * 492 + 14, 32767); }
            Integer(r, ta + 204, 0x4b47a0 + actor * 492);
            Integer(r, ta + 28, profile == 2 ? 66086 : 550); Integer(r, ta + 32, profile == 2 ? -65836 : 290); Integer(r, ta + 304, 2);
            if (whole) { Word(f, at + 40, -1); f[at + 482] = 255; }
            fleets = f; backing = new PracticeAiSharedBacking(r);
        }

        internal static void Run(Action<string, Action> check, Action<string, Action> evidence, string assets)
        {
            var bases = Bases(assets);
            check("Idle return matches48 original654 complete fleet/shared-region golden states", delegate
            {
                int count = 0;
                foreach (string line in Original)
                {
                    var row = line.Split(','); int id = int.Parse(row[0]), preset = int.Parse(row[1]), actor = int.Parse(row[2]), slot = int.Parse(row[3]);
                    int state = int.Parse(row[4]), profile = int.Parse(row[5]), selected = int.Parse(row[6]); byte[] f; PracticeAiSharedBacking b;
                    Fixture(bases[preset], id, actor, slot, state, profile, false, out f, out b);
                    var result = PracticeIdleReturn.Apply(f, b, slot, 0, selected);
                    Need(row.Length == 13 && id == count && slot == id * 47 % 250 && result.LinkedFleet == actor && result.SelectedWaypoint == int.Parse(row[7]) && result.RouteUiRequests == int.Parse(row[8]) && Hash(f) == row[9] && Hash(result.CopyFleetPool()) == row[10] && Hash(b.CopyRegion()) == row[11] && Hash(result.Backing.CopyRegion()) == row[12], "Original654 complete state " + id); count++;
                }
                Need(count == 48, "654 golden count");
            });
            check("Idle states preserve signed cached DWORDs and truncate only fleet waypoints", delegate
            {
                byte[] f; PracticeAiSharedBacking b; Fixture(bases[0], 0, 16, 7, 6, 2, false, out f, out b);
                var result = PracticeIdleReturn.Apply(f, b, 7, 0, 4); var task = result.Backing.CopyTaskRecord(7); var after = result.CopyFleetPool();
                Need(result.DestinationX == 66086 && result.DestinationY == -65836 && BitConverter.ToInt32(task, 8) == 66086 && BitConverter.ToInt32(task, 12) == -65836 && BitConverter.ToInt16(after, 16 * 492 + 40) == 550 && BitConverter.ToInt16(after, 16 * 492 + 50) == -300 && result.RouteUiRequests == 1 && result.SelectedWaypoint == -1 && BitConverter.ToInt32(task, 304) == 0, "DWORD destination or queue activity changed");
                for (int n = 1; n < 5; n++) Need(BitConverter.ToInt16(after, 16 * 492 + 40 + n * 2) == -1 && BitConverter.ToInt16(after, 16 * 492 + 50 + n * 2) == 200 + n * 10, "Opaque Y or cleared X " + n);
                Fixture(bases[0], 0, 16, 7, 5, 0, false, out f, out b); result = PracticeIdleReturn.Apply(f, b, 7, 0, -1); task = result.Backing.CopyTaskRecord(7);
                Need(BitConverter.ToInt32(task, 28) == BitConverter.ToInt16(f, 16 * 492 + 12) && BitConverter.ToInt32(task, 32) == BitConverter.ToInt16(f, 16 * 492 + 14) && result.DestinationX == BitConverter.ToInt16(f, 12) && result.DestinationY == BitConverter.ToInt16(f, 14), "State5 origin cache/reference destination");
            });
            check("Idle return leaves owned parents and opaque shared tail unchanged", delegate
            {
                byte[] f; PracticeAiSharedBacking b; Fixture(bases[0], 0, 249, 7, 5, 0, false, out f, out b); string fh = Hash(f), bh = Hash(b.CopyRegion());
                var result = PracticeIdleReturn.Apply(f, b, 7, 0, 4); var copy = result.CopyFleetPool(); copy[0] ^= 255;
                Need(Hash(f) == fh && Hash(b.CopyRegion()) == bh && copy[0] != result.CopyFleetPool()[0] && result.Backing.CopyRegion()[78559] == b.CopyRegion()[78559] && BitConverter.ToInt32(b.CopyTaskRecord(7), 304) == 2, "Mutable idle result/parent or discarded tail");
            });
            check("Idle return rejects malformed links unsupported state and networking before publication", delegate
            {
                byte[] f; PracticeAiSharedBacking b; Fixture(bases[0], 0, 16, 7, 5, 0, false, out f, out b); string h = Hash(b.CopyRegion());
                Need(Reject(delegate { PracticeIdleReturn.Apply(new byte[1], b, 7, 0, 0); }) && Reject(delegate { PracticeIdleReturn.Apply(f, null, 7, 0, 0); }) && Reject(delegate { PracticeIdleReturn.Apply(f, b, 250, 0, 0); }) && Reject(delegate { PracticeIdleReturn.Apply(f, b, 7, 1, 0); }) && Reject(delegate { PracticeIdleReturn.Apply(f, b, 7, 0, 5); }), "Malformed idle input admitted");
                Word(f, 16 * 492 + 488, -1); Need(Reject(delegate { PracticeIdleReturn.Apply(f, b, 7, 0, 0); }), "Invalid home admitted");
                Integer(f, 16 * 492 + 472, 4); Need(Reject(delegate { PracticeIdleReturn.Apply(f, b, 7, 0, 0); }), "Unsupported state admitted");
                var task = b.CopyTaskRecord(7); Integer(task, 204, 0x4b47a1); var bad = b.WithTaskRecord(7, task);
                Need(Reject(delegate { PracticeIdleReturn.Apply(f, bad, 7, 0, 0); }) && Hash(b.CopyRegion()) == h, "Malformed reference changed predecessor");
            });
            evidence("Canonical idle return matches all48 original654 full input/output snapshots", delegate
            {
                string path = Path.Combine(Path.GetDirectoryName(assets), "Evidence", "Idle-Return-654.bin");
                Need(Hash(File.ReadAllBytes(path)) == "038D3BCC82AF4BB6E0188FB0869A5DC6AE268A6CDEB0DD3DE2D89A1601F8252E", "654 capture identity"); int count = 0;
                using (var r = new BinaryReader(File.OpenRead(path)))
                {
                    Need(System.Text.Encoding.ASCII.GetString(Read(r, 8)) == "IR654001" && r.ReadInt32() == 1 && r.ReadInt32() == 48, "654 header"); var bf = Read(r, 123000); var br = Read(r, 78560);
                    for (;;)
                    {
                        int id = r.ReadInt32(); if (id == -1) break; int preset = r.ReadInt32(), actor = r.ReadInt32(), slot = r.ReadInt32(), state = r.ReadInt32(), profile = r.ReadInt32(), selected = r.ReadInt32(), wp = r.ReadInt32(), requests = r.ReadInt32();
                        Need(id == count && preset >= 0 && preset < 2 && (actor == 16 || actor == 249) && slot == id * 47 % 250 && (state == 5 || state == 6) && profile >= 0 && profile < 3, "654 metadata");
                        var f = Patch(r, bf); var b = Patch(r, br); var af = Patch(r, f); var ab = Patch(r, b); var result = PracticeIdleReturn.Apply(f, new PracticeAiSharedBacking(b), slot, 0, selected);
                        Need(Hash(result.CopyFleetPool()) == Hash(af) && Hash(result.Backing.CopyRegion()) == Hash(ab) && result.SelectedWaypoint == wp && result.RouteUiRequests == requests, "654 full snapshots " + id); count++;
                    }
                    Need(count == 48 && r.BaseStream.Position == r.BaseStream.Length, "654 count/EOF");
                }
            });
        }
    }
